 brief="પહેલાં દબાણ ખસેડવાવાળા આવીને માલ, કટ્ટા ને ત્રાજવું ખટારામાં લઈ જતા, ને છોડાવતાં સુધીમાં માલ બગડી જતો.",
 summary="પાલુબેન પહેલાંના દિવસો યાદ કરે છે. મ્યુનિસિપાલિટીવાળા, પોલીસ ને દબાણ ખસેડવાવાળા ખટારા લઈને આવતા અને બધો માલ, કટ્ટા ને ત્રાજવું ઉપાડી જતા. છેક ગોડાઉને જઈ પૈસા ભરે ત્યારે માલ છૂટતો, ને ત્યાં સુધીમાં સાંજ પડી જતી ને માલ ખરાબ થઈ જતો.",
 detailed="આ ભાગમાં પાલુબેન પહેલાંના દિવસો યાદ કરે છે. ધંધો માંડ ચાલતો હોય ત્યાં મ્યુનિસિપાલિટીવાળા, પોલીસ ને દબાણ ખસેડવાવાળા ખટારા લઈને આવતા. એમને પાથરણાં દબાણ લાગતાં — દબાણ એટલે જાહેર જગ્યા પર કરેલો ગેરકાયદે કબજો. બધો માલ, માલના કટ્ટા ને ત્રાજવું બધુંય ખટારામાં ચડી જતું. છેક ગોડાઉને જઈને પૈસા ભરે ત્યારે જ માલ છૂટતો, અને માલ છોડાવવામાં સાંજ પડી જતી. ત્યાં સુધીમાં શાકભાજી ખરાબ થઈ જતું. ટ્રાફિક પોલીસ ને મ્યુનિસિપાલિટી સાથે લડવાડ ચાલતી, પણ પાલુબેન કહે છે કે આખરે નુકસાન તો એમનું જ થતું.",
 bullets=["દબાણ — જાહેર જગ્યા પર કરેલો ગેરકાયદે કબજો.",
          "ખટારો — માલ ભરવાની મોટી ગાડી.",
          "કટ્ટા — માલ ભરવાની મોટી કોથળી.",
          "ગોડાઉન — માલ ભરવાની વખાર, ગોદામ."],
 points=["ખટારો આવે — માલ, કટ્ટા ને ત્રાજવું ઉપાડી જવાય.",
         "છોડાવવા — છેક ગોડાઉને જઈ પૈસા ભરવા પડે.",
         "એટલી વારમાં — સાંજ પડે ને શાક બગડે.",
         "પાલુબેનનું વાક્ય — ‘આખરે નુકસાન તો અમારું જ થતું.’"],
 ex="5",
 rq=[("દબાણ ખસેડવાવાળા આવે ત્યારે ખટારામાં શું શું લઈ જવાતું ?",
      "બધો માલ, માલના કટ્ટા ને ત્રાજવું — બધુંય ખટારામાં લઈ જવાતું.","easy","remember"),
     ("માલ છોડાવવા શું કરવું પડતું, ને એટલી વારમાં માલનું શું થતું ?",
      "છેક ગોડાઉને જઈને પૈસા ભરવા પડતા. માલ છોડાવવામાં સાંજ પડી જતી અને ત્યાં સુધીમાં માલ ખરાબ થઈ જતો.","medium","understand"),
     ("‘આખરે નુકસાન તો અમારું જ થતું.’ — ખટારો આવ્યા પછી શું શું બન્યું તે ક્રમમાં ગોઠવીને આ વાક્યનો અર્થ સમજાવો.",
      "પહેલાં માલ, કટ્ટા ને ત્રાજવું ખટારામાં ચડી જતાં. પછી ગોડાઉને જઈને પૈસા ભરવા પડતા. પછી માલ છૂટતાં સાંજ પડી જતી ને શાકભાજી બગડી જતું. એટલે પૈસા પણ ગયા ને માલ પણ ગયો — તેથી પાલુબેન કહે છે કે નુકસાન છેવટે એમનું જ થતું.","hard","analyze")],
 shabdarth=[("દબાણ","જાહેર જગ્યા પર કરેલો ગેરકાયદે કબજો.","તદ્ભવ"),
            ("ખટારા","માલ ભરવાની મોટી ગાડી, ટ્રક.","દેશ્ય"),
            ("કટ્ટા","માલ ભરવાની મોટી કોથળી.","દેશ્ય"),
            ("ગોડાઉન","માલ ભરવાની વખાર, ગોદામ.","આગત"),
            ("લડવાડ","ઝઘડો, તકરાર.","દેશ્ય")],
 samanarthi=[("નુકસાન",["ખોટ","હાનિ"]),("લડવાડ",["ઝઘડો","તકરાર"])],
 vilom=[("નુકસાન","નફો")],
 vyakaran=[("ઉપસર્ગ-પ્રત્યય","મ્યુનિસિપાલિટીવાળા, પોલીસ, દબાણ ખસેડવાવાળા ખટારા લઈને આવે.",
   "‘-વાળા’ પ્રત્યય લાગે એટલે ‘એ કામ કરનાર’ એવો અર્થ થાય છે — ‘મ્યુનિસિપાલિટીવાળા’ ને ‘દબાણ ખસેડવાવાળા’. પ્રત્યય લાગતાં શબ્દનો અર્થ બદલાય છે.")],
 concepts={"M3.S4.T8.C9":[
   ("paragraph","પાલુબેન પહેલાંના દિવસો યાદ કરે છે. ધંધો માંડ ચાલતો હોય ત્યાં મ્યુનિસિપાલિટીવાળા, પોલીસ ને દબાણ ખસેડવાવાળા ખટારા લઈને આવતા. દબાણ એટલે જાહેર જગ્યા પર કરેલો ગેરકાયદે કબજો — રસ્તા પર પાથરેલું પાથરણું એમને દબાણ લાગતું."),
   ("list",["માલ, કટ્ટા ને ત્રાજવું ખટારામાં ચડી જતાં.","છેક ગોડાઉને જઈ પૈસા ભરવા પડતા.","માલ છોડાવવામાં સાંજ પડી જતી.","ત્યાં સુધીમાં માલ ખરાબ થઈ જતો."]),
   ("paragraph","ખટારો એટલે માલ ભરવાની મોટી ગાડી ને ગોડાઉન એટલે માલ ભરવાની વખાર. લડવાડ ચાલતી, પણ પાલુબેન પોતે જ કહી દે છે — ‘આખરે નુકસાન તો અમારું જ થતું.’")]},
